import { defineStore } from 'pinia';

export const useAuthStore = defineStore('auth', {
  state: () => ({
    user: {
      username: 'admin',
      role: 'ADMIN'
    },
    csrfToken: ''
  }),
  getters: {
    username: (state) => state.user?.username ?? 'guest',
    role: (state) => state.user?.role ?? 'EMPLOYER',
    isLoggedIn: (state) => Boolean(state.user),
    initials: (state) => {
      if (!state.user?.username) return 'SW';
      return state.user.username
        .split(' ')
        .map((chunk) => chunk[0])
        .join('')
        .slice(0, 2)
        .toUpperCase();
    }
  },
  actions: {
    setCsrf(token) {
      this.csrfToken = token;
    },
    setUser(user) {
      this.user = user;
    },
    logout() {
      this.user = null;
      window.location.href = '/login';
    }
  }
});

