+        if (entry == null || entry.expiresAt().isBefore(Instant.now())) {
+            captchaStore.remove(id);
+            return false;
+        }
+        boolean matches = entry.answer().equalsIgnoreCase(answer.trim());
+        if (matches) {
+            captchaStore.remove(id);
+        }
+        return matches;
+    }
+
