        user.setUsername(request.getUsername());
        user.setEmail(request.getEmail());
        user.setRole(UserRole.EMPLOYER);
        user.setStatus(UserStatus.ACTIVE);
        user.setPasswordHash(passwordEncoder.encode(request.getPassword()));
        user.setPasswordChangedAt(Instant.now());
        user.setCreatedAt(Instant.now());
        user.setUpdatedAt(Instant.now());
        User saved = userRepository.save(user);
        return UserResponse.from(saved);
    }

    @Transactional
    public void logout(Long userId) {
        sessionService.invalidateAllSessions(userId);
    }

    @Transactional
    public void changePassword(Long userId, ChangePasswordRequest request) {
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new BusinessException(HttpStatus.NOT_FOUND, "User not found"));
        if (!passwordEncoder.matches(request.getCurrentPassword(), user.getPasswordHash())) {
            throw new BusinessException(HttpStatus.BAD_REQUEST, "Current password is incorrect");
        }
        var violations = passwordPolicyService.validate(request.getNewPassword());
        if (!violations.isEmpty()) {
            throw new BusinessException(HttpStatus.BAD_REQUEST, violations.get(0));
        }
        user.setPasswordHash(passwordEncoder.encode(request.getNewPassword()));
        user.setPasswordChangedAt(Instant.now());
        userRepository.save(user);
        sessionService.invalidateAllSessions(userId);
    }

