import java.util.concurrent.ConcurrentHashMap;

@Slf4j
@Component
@RequiredArgsConstructor
public class RateLimitFilter extends OncePerRequestFilter {

    private static final int AUTH_LIMIT = 20;
    private static final int USER_LIMIT = 60;

    private final SessionService sessionService;

    private final Map<Long, BucketHolder> userBuckets = new ConcurrentHashMap<>();
    private final Map<String, BucketHolder> ipBuckets = new ConcurrentHashMap<>();

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain) throws ServletException, IOException {
        Long userId = resolveUserId(request);
        boolean isAuthEndpoint = request.getRequestURI().startsWith("/api/auth");
        if (userId != null) {
            if (!allowRequest(userBuckets, userId.toString(), USER_LIMIT)) {
                writeRateLimitResponse(response);
                return;
            }
        } else if (isAuthEndpoint) {
            String key = request.getRemoteAddr();
            if (!allowRequest(ipBuckets, key, AUTH_LIMIT)) {
                writeRateLimitResponse(response);
                return;
            }
        }
        filterChain.doFilter(request, response);
    }

    private boolean allowRequest(Map<?, BucketHolder> buckets, String key, int limit) {
        BucketHolder holder = buckets.computeIfAbsent(key, k -> new BucketHolder(new TokenBucket(limit, limit)));
        holder.touch();
        return holder.bucket().tryConsume();
    }

    private Long resolveUserId(HttpServletRequest request) {
        return CookieUtils.getCookie(request, SessionService.SESSION_COOKIE)
            .flatMap(sessionService::findValidSession)
            .map(session -> {
                request.setAttribute(SessionAuthFilter.SESSION_REQUEST_ATTRIBUTE, session);
                return session.getUser().getId();
            })
            .orElse(null);
    }

    private void writeRateLimitResponse(HttpServletResponse response) throws IOException {
        response.setStatus(429);
        response.setContentType("application/json");
        response.getWriter().write("{\"code\":429,\"message\":\"Rate limit exceeded\"}");
    }

    @Scheduled(fixedDelay = 300_000)
    public void cleanBuckets() {
        Instant cutoff = Instant.now().minusSeconds(600);
        userBuckets.entrySet().removeIf(entry -> entry.getValue().lastTouched().isBefore(cutoff));
        ipBuckets.entrySet().removeIf(entry -> entry.getValue().lastTouched().isBefore(cutoff));
    }

    private record BucketHolder(TokenBucket bucket, Instant lastTouched) {
        BucketHolder(TokenBucket bucket) {
            this(bucket, Instant.now());
