    public void cleanBuckets() {
        Instant cutoff = Instant.now().minusSeconds(600);
        userBuckets.entrySet().removeIf(entry -> entry.getValue().lastTouched.isBefore(cutoff));
        ipBuckets.entrySet().removeIf(entry -> entry.getValue().lastTouched.isBefore(cutoff));
    }

    private static final class BucketHolder {
        private final TokenBucket bucket;
        private volatile Instant lastTouched;

        private BucketHolder(TokenBucket bucket) {
            this.bucket = bucket;
            this.lastTouched = Instant.now();
        }

        private void touch() {
            this.lastTouched = Instant.now();
        }
    }
}

