                .requestMatchers("/api/auth/login", "/api/auth/register", "/api/auth/captcha").permitAll()
                .requestMatchers("/actuator/health").permitAll()
                .requestMatchers("/api/**").authenticated()
                .anyRequest().permitAll());
        http.addFilterBefore(csrfValidationFilter, UsernamePasswordAuthenticationFilter.class);
        http.addFilterBefore(sessionAuthFilter, CsrfValidationFilter.class);
        http.addFilterBefore(rateLimitFilter, SessionAuthFilter.class);
        return http.build();
    }

