+        <div class="metric-card">
+          <span>Pending Reviews</span>
+          <strong>{{ metrics.pendingReviews }}</strong>
+        </div>
+      </el-col>
+      <el-col :xs="24" :md="8">
+        <div class="metric-card">
+          <span>Pending Appeals</span>
+          <strong>{{ metrics.pendingAppeals }}</strong>
