+      <el-table-column label="Job" prop="jobTitle" />
+      <el-table-column label="Action">
+        <template #default="{ row }">
+          <el-tag :type="statusType[row.action] || 'info'">{{ row.action }}</el-tag>
+        </template>
+      </el-table-column>
+      <el-table-column label="Rationale" prop="rationale" />
+      <el-table-column label="Date">
+        <template #default="{ row }">{{ new Date(row.createdAt).toLocaleString() }}</template>
+      </el-table-column>
+    </el-table>
+  </section>
+</template>
+
+<style scoped>
+.dashboard-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+}
+
+.metric-row {
+  margin-top: 16px;
+  margin-bottom: 24px;
+}
+
+.metric-card {
+  background: #0a1d37;
+  color: #f5f7ff;
+  border-radius: 16px;
+  padding: 20px;
+}
+
+.metric-card span {
+  display: block;
+  font-size: 13px;
+  opacity: 0.8;
+}
+
+.metric-card strong {
+  font-size: 32px;
+}
+</style>
