+<script setup>
+import { onMounted, ref } from 'vue';
+import { useRoute, useRouter } from 'vue-router';
+import { ElMessage } from 'element-plus';
+import appealsApi from '@/api/appeals';
+
+const route = useRoute();
+const router = useRouter();
+const appealId = route.params.id;
+const appeal = ref(null);
+const loading = ref(false);
+const actionDialog = ref({ visible: false, decision: 'GRANTED', rationale: '' });
+
+const loadAppeal = async () => {
+  loading.value = true;
+  try {
+    const { data } = await appealsApi.getAppeal(appealId);
+    appeal.value = data;
+  } finally {
+    loading.value = false;
+  }
+};
+
+onMounted(loadAppeal);
+
+const openDialog = (decision) => {
+  actionDialog.value = { visible: true, decision, rationale: '' };
+};
+
+const processAppeal = async () => {
+  if (actionDialog.value.rationale.length < 10) {
+    ElMessage.warning('Please provide rationale with at least 10 characters');
+    return;
+  }
+  await appealsApi.processAppeal(appealId, {
+    decision: actionDialog.value.decision,
+    reviewerRationale: actionDialog.value.rationale
+  });
+  ElMessage.success(`Appeal ${actionDialog.value.decision.toLowerCase()}`);
+  actionDialog.value.visible = false;
+  loadAppeal();
+};
+
+const statusType = {
+  PENDING: 'warning',
+  GRANTED: 'success',
+  DENIED: 'danger'
+};
+</script>
+
+<template>
