+        <p>{{ appeal.appealReason }}</p>
+      </el-card>
+      <el-card class="mb-16">
+        <h3>Takedown Context</h3>
+        <p><strong>Reason:</strong> {{ appeal.takedownReason || 'N/A' }}</p>
+        <p><strong>Reviewer Rationale:</strong> {{ appeal.takedownRationale || 'N/A' }}</p>
