    }

    @Transactional(readOnly = true)
    public List<ReviewActionResponse> actionsForJob(Long jobId) {
        return reviewActionRepository.findByJobPosting_IdOrderByCreatedAtDesc(jobId).stream()
            .map(this::toActionResponse)
            .toList();
    }

