*** Update File: frontend/src/views/AdminDashboardView.vue
@@
-<template>
-  <section class="page-card">
-    <h1>Admin Control Center</h1>
-    <p>High-level overview of system health and backlog.</p>
-  </section>
-</template>
+<script setup>
+import { computed, onMounted, ref } from 'vue';
+import VChart from 'vue-echarts';
+import adminApi from '@/api/admin';
+
+const counts = ref({
+  totalUsers: 0,
+  activePostings: 0,
+  pendingReviews: 0,
+  openClaims: 0,
+  openTickets: 0,
+  unreadAlerts: 0
+});
+
+const volume = ref([]);
+const statusData = ref([]);
+const loading = ref(false);
+
+const loadDashboard = async () => {
+  loading.value = true;
+  try {
+    const [countsRes, volumeRes, statusRes] = await Promise.all([
+      adminApi.getAdminStats(),
+      adminApi.getPostVolume({ days: 30 }),
+      adminApi.getPostStatusDistribution()
+    ]);
+    counts.value = countsRes.data;
+    volume.value = volumeRes.data;
+    statusData.value = statusRes.data;
+  } finally {
+    loading.value = false;
+  }
+};
+
+onMounted(loadDashboard);
+
+const metricCards = computed(() => ([
+  { label: 'Total Users', value: counts.value.totalUsers },
+  { label: 'Active Postings', value: counts.value.activePostings },
+  { label: 'Pending Reviews', value: counts.value.pendingReviews },
+  { label: 'Open Claims', value: counts.value.openClaims },
+  { label: 'Open Tickets', value: counts.value.openTickets },
+  { label: 'Unread Alerts', value: counts.value.unreadAlerts }
+]));
+
+const volumeOptions = computed(() => ({
+  tooltip: { trigger: 'axis' },
+  xAxis: {
+    type: 'category',
+    data: volume.value.map((point) => point.date)
+  },
+  yAxis: { type: 'value' },
+  series: [
+    {
+      type: 'line',
+      smooth: true,
+      areaStyle: {},
+      data: volume.value.map((point) => point.count)
+    }
+  ]
+}));
+
+const statusOptions = computed(() => ({
+  tooltip: { trigger: 'item' },
+  legend: { bottom: 0 },
+  series: [
+    {
+      type: 'pie',
+      radius: ['40%', '70%'],
+      data: statusData.value.map((item) => ({ name: item.status, value: item.count }))
+    }
+  ]
+}));
+</script>
+
+<template>
+  <section class="page-card" v-loading="loading">
+    <div class="header">
+      <div>
+        <h1>Admin Control Center</h1>
+        <p class="muted">Monitor key signals across postings, reviews, and support.</p>
+      </div>
+    </div>
+    <el-row :gutter="16" class="metrics-grid">
+      <el-col v-for="card in metricCards" :key="card.label" :xs="12" :md="8">
+        <div class="metric-card">
+          <span>{{ card.label }}</span>
+          <strong>{{ card.value }}</strong>
+        </div>
+      </el-col>
+    </el-row>
