        return executeQuery(config);
    }

    private List<Map<String, Object>> executeQuery(DashboardConfig config) {
        List<String> metrics = objectMapper.convertValue(config.getMetricsJson(), new TypeReference<>() {});
        String dimension = objectMapper.convertValue(config.getDimensionsJson(), String.class);
        Map<String, Object> filters = config.getFiltersJson() != null ? objectMapper.convertValue(config.getFiltersJson(), Map.class) : Map.of();

        Map<String, Map<String, Object>> rows = new LinkedHashMap<>();
        for (String metric : metrics) {
            List<Map<String, Object>> results = queryMetric(metric, dimension, filters);
            for (Map<String, Object> row : results) {
                String key = row.get("dimension").toString();
                Map<String, Object> entry = rows.computeIfAbsent(key, k -> {
                    Map<String, Object> map = new LinkedHashMap<>();
                    map.put("dimension", k);
                    return map;
                });
                entry.put(metric, row.get("value"));
            }
        }
        return new ArrayList<>(rows.values());
    }

    private List<Map<String, Object>> queryMetric(String metric, String dimension, Map<String, Object> filters) {
        String table;
        String condition = "";
        String join = "";
        switch (metric) {
            case "post_volume":
                table = "job_postings";
                break;
            case "claim_count":
                table = "claims";
                break;
            case "review_count":
            case "approval_rate":
            case "handling_time":
            case "takedown_count":
                table = "review_actions";
                break;
            default:
                throw new BusinessException(HttpStatus.BAD_REQUEST, "metric: Unsupported");
        }
        Instant from = filters.containsKey("dateFrom") ? Instant.parse(filters.get("dateFrom").toString()) : Instant.now().minusSeconds(30 * 86400);
        Instant to = filters.containsKey("dateTo") ? Instant.parse(filters.get("dateTo").toString()) : Instant.now();
        List<String> statuses = filters.containsKey("statuses") ? (List<String>) filters.get("statuses") : List.of();

        String dimensionExpr = resolveDimension(dimension, table);
        String base = switch (dimension) {
            case "status" -> "job_postings.status";
            case "category" -> "categories.name";
            case "location_state" -> "locations.state";
            case "reviewer" -> "users.username";
            default -> dimensionExpr;
        };

        String metricExpr = switch (metric) {
            case "post_volume", "claim_count", "review_count" -> "COUNT(*)";
            case "approval_rate" -> "SUM(CASE WHEN action = 'APPROVE' THEN 1 ELSE 0 END)";
            case "handling_time" -> "AVG(TIMESTAMPDIFF(HOUR, jp.created_at, ra.created_at))";
            case "takedown_count" -> "SUM(CASE WHEN action = 'TAKEDOWN' THEN 1 ELSE 0 END)";
            default -> "COUNT(*)";
        };

        String sql = "SELECT " + dimensionExpr + " AS dimension, " + metricExpr + " AS value FROM " + table + " ";
        if (dimension.equals("category")) {
            sql += "JOIN categories ON categories.id = job_postings.category_id ";
        }
        if (dimension.equals("location_state")) {
            sql += "JOIN locations ON locations.id = job_postings.location_id ";
        }
        if (dimension.equals("reviewer")) {
            sql += "JOIN users ON users.id = review_actions.reviewer_id ";
        }
        sql += "WHERE created_at >= :from AND created_at <= :to ";
        if (!statuses.isEmpty()) {
            sql += "AND job_postings.status IN (" + statuses.stream().map(s -> "'" + s + "'").reduce((a, b) -> a + "," + b).orElse("") + ") ";
        }
        if (metric.equals("handling_time")) {
            sql += "AND review_actions.job_posting_id = job_postings.id ";
            sql += "JOIN job_postings jp ON jp.id = review_actions.job_posting_id ";
        }
        sql += "GROUP BY dimension ORDER BY dimension";

        Query query = entityManager.createNativeQuery(sql);
        query.setParameter("from", from);
        query.setParameter("to", to);
        List<Object[]> raw = query.getResultList();
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Object[] row : raw) {
            Map<String, Object> map = new HashMap<>();
            map.put("dimension", row[0]);
            map.put("value", row[1]);
            rows.add(map);
        }
        return rows;
    }

    private String resolveDimension(String dimension, String table) {
        return switch (dimension) {
            case "date_daily" -> "DATE(created_at)";
            case "date_weekly" -> "DATE_FORMAT(created_at, '%x-%v')";
            case "date_monthly" -> "DATE_FORMAT(created_at, '%Y-%m')";
            case "status" -> "job_postings.status";
            case "category" -> "categories.name";
            case "location_state" -> "locations.state";
            case "reviewer" -> "users.username";
            default -> "DATE(created_at)";
        };
    }

    private byte[] toCsv(List<Map<String, Object>> rows) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             OutputStreamWriter writer = new OutputStreamWriter(bos, StandardCharsets.UTF_8);
             CSVPrinter printer = new CSVPrinter(writer, CSVFormat.DEFAULT.withHeader(rows.get(0).keySet().toArray(new String[0])))) {
            for (Map<String, Object> row : rows) {
                printer.printRecord(row.values());
            }
            printer.flush();
            return bos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private DashboardConfigResponse toResponse(DashboardConfig config) {
        return new DashboardConfigResponse(config.getId(), config.getName(), config.getMetricsJson(), config.getDimensionsJson(), config.getFiltersJson());
    }
}

