+<script setup>
+import { onMounted, onUnmounted, ref } from 'vue';
+import alertsApi from '@/api/alerts';
+import { ElMessage } from 'element-plus';
+
+const tabs = ['All', 'Unread', 'Critical', 'Warning'];
+const activeTab = ref('All');
+const alerts = ref([]);
+const loading = ref(false);
+let intervalId;
+
+const severityMap = {
+  All: null,
+  Unread: null,
+  Critical: 'CRITICAL',
+  Warning: 'WARNING'
+};
+
+const fetchAlerts = async () => {
+  loading.value = true;
+  try {
+    const params = { page: 0, size: 20 };
+    if (severityMap[activeTab.value]) {
+      params.severity = severityMap[activeTab.value];
+    }
+    if (activeTab.value === 'Unread') {
+      params.is_read = false;
+    }
+    const { data } = await alertsApi.getAlerts(params);
+    alerts.value = data.content;
+  } finally {
+    loading.value = false;
+  }
+};
+
+const markRead = async (id) => {
+  await alertsApi.markAlertRead(id);
+  ElMessage.success('Marked as read');
+  fetchAlerts();
+};
+
+const acknowledge = async (id) => {
+  await alertsApi.acknowledgeAlert(id);
+  ElMessage.success('Acknowledged');
+  fetchAlerts();
+};
+
+onMounted(() => {
+  fetchAlerts();
+  intervalId = setInterval(fetchAlerts, 30000);
+});
+
+onUnmounted(() => {
+  clearInterval(intervalId);
+});
